import {brandMark} from './brand.js';
import '@fontsource/ibm-plex-sans/latin-400.css';
import '@fontsource/ibm-plex-sans/latin-500.css';
import '@fontsource/ibm-plex-sans/latin-600.css';
import './style.css';
import {showPasswordDialog,showSplitDialog} from './document-actions.js';
import {saveRecent,getRecent,listRecent} from './recents.js';
import {readDrafts,writeDraft} from './draft.js';
import {renderUpdates,updateAction,startUpdates} from './updates.js';
import {track,working} from './work.js';
import { createIcons, Layers2, Minus, Square, X, Files, Printer, Scan, FolderOpen, Settings2, ShieldCheck, MoreHorizontal, Plus, Download, FileText, LayoutGrid, LockKeyhole, SlidersHorizontal, GripVertical, ArrowUp, ArrowDown, FilePlus2, RotateCw, ChevronLeft, ChevronRight, CircleCheck, Pause, Play, House, Undo2, Redo2, Copy, Trash2, Scissors, CheckSquare, Eye, Pencil } from 'lucide';
const icons={Layers2,Minus,Square,X,Files,Printer,Scan,FolderOpen,Settings2,ShieldCheck,MoreHorizontal,Plus,Download,FileText,LayoutGrid,LockKeyhole,SlidersHorizontal,GripVertical,ArrowUp,ArrowDown,FilePlus2,RotateCw,ChevronLeft,ChevronRight,CircleCheck,Pause,Play,House,Undo2,Redo2,Copy,Trash2,Scissors,CheckSquare,Eye,Pencil};
import { PDFDocument, degrees } from 'pdf-lib';
import * as pdfjs from 'pdfjs-dist';
import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
pdfjs.GlobalWorkerOptions.workerSrc = workerUrl;
const $ = (s) => document.querySelector(s);
const icon = (name) => `<i data-lucide="${name}"></i>`;
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = { files:[], selected:null, page:1, zoom:100, fit:true, actualZoom:100, rangeMode:'all', customRange:'', view:'combine', tab:'document', rotation:{}, busy:false, output:'pdf', name:'Merged document.pdf', showOutput:false, openAfter:true, bookmarks:true, quality:'standard', workflow:'add', completed:null, pageOrder:null, selectedPages:new Set(), selectionAnchor:null, savedDraft:null, workspace:'merge', workspaceView:'combine' };
let mergedBytes, pdf, renderVersion=0, toastTimer;
const thumbnailCache=new Map();
const sourceViews=new Map(), pageImages=new Map(), sourceDocuments=new Map();
let history={undo:[],redo:[]},draftTimer,draftChain=Promise.resolve();
// Document (Preview/Edit) and Merge each keep these fields and their own undo history; the inactive one waits in parked.
const workspaceFields=['files','pageOrder','rotation','page','name','rangeMode','customRange','selectedPages','selectionAnchor','workflow','completed','zoom','fit','tab','savedDraft','workspaceView'];
function blankWorkspace(key){return {files:[],pageOrder:null,rotation:{},page:1,name:'Merged document.pdf',rangeMode:'all',customRange:'',selectedPages:new Set(),selectionAnchor:null,workflow:key==='merge'?'add':'review',completed:null,zoom:100,fit:true,tab:'document',savedDraft:null,workspaceView:key==='merge'?'combine':'preview',history:{undo:[],redo:[]}}}
const parked={document:blankWorkspace('document')};
function workspaceOf(view){return {combine:'merge',preview:'document',edit:'document'}[view]||null}
function loadWorkspace(w){const {history:h,...fields}=w;Object.assign(state,fields);history=h}
function setView(view){const next=workspaceOf(view);if(next&&next!==state.workspace){if(draftTimer)saveActiveDraft();parked[state.workspace]={...Object.fromEntries(workspaceFields.map(k=>[k,state[k]])),history};loadWorkspace(parked[next]);state.workspace=next}if(next)state.workspaceView=view;state.view=view}
function snapshotWorkspace(w=state){if(w===state)ensurePageOrder();return {files:[...w.files],pageOrder:w.pageOrder?.map(p=>({...p}))??null,rotation:{...w.rotation},page:w.page,name:w.name,rangeMode:w.rangeMode,customRange:w.customRange,view:w.workspaceView,selectedPages:[...w.selectedPages],selectionAnchor:w.selectionAnchor,savedAt:Date.now()}}
function remember(){history.undo.push(snapshotWorkspace());if(history.undo.length>40)history.undo.shift();history.redo=[];updateHistoryButtons()}
function queueDraft(key,w=state){draftTimer=clearTimeout(draftTimer);const value=snapshotWorkspace(w);w.savedDraft=value;return draftChain=draftChain.catch(()=>{}).then(()=>writeDraft(value,key)).then(()=>{const el=$('#draft-status');if(el)el.textContent='Draft saved on this device'})}
function saveActiveDraft(){queueDraft(state.workspace).catch(()=>toast('Draft could not be saved. Export your PDF to keep your work.'))}
function scheduleDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(saveActiveDraft,300)}
function restoreSnapshot(value){state.files=[...value.files];state.pageOrder=value.pageOrder?.map(p=>({...p}))??null;state.rotation={...value.rotation};state.page=value.page;state.name=value.name;state.rangeMode=value.rangeMode||'all';state.customRange=value.customRange||'';state.selectedPages=new Set(value.selectedPages||[]);state.selectionAnchor=value.selectionAnchor||null;state.workflow='review';state.completed=null;state.page=Math.max(1,Math.min(state.page,total()))}
function undoRedo(which){const from=history[which],to=history[which==='undo'?'redo':'undo'];if(!from.length)return;to.push(snapshotWorkspace());restoreSnapshot(from.pop());refreshEditingUI();scheduleDraft();toast(which==='undo'?'Change undone.':'Change restored.')}
function updateHistoryButtons(){document.querySelectorAll('[data-edit=undo]').forEach(b=>b.disabled=!history.undo.length);document.querySelectorAll('[data-edit=redo]').forEach(b=>b.disabled=!history.redo.length)}
async function sourceView(file){if(!sourceViews.has(file.id))sourceViews.set(file.id,pdfjs.getDocument({data:file.bytes.slice()}).promise);return sourceViews.get(file.id)}
async function sourceDocument(file){if(!sourceDocuments.has(file.id))sourceDocuments.set(file.id,PDFDocument.load(file.bytes));return sourceDocuments.get(file.id)}
function pageIdentity(index){return state.pageOrder?.[index]?.uid}

function defaultPageOrder(){return state.files.flatMap(f=>Array.from({length:f.pages},(_,local)=>({fileId:f.id,local,uid:crypto.randomUUID()})))}
function ensurePageOrder(){if(state.pageOrder===null)state.pageOrder=defaultPageOrder();const files=new Map(state.files.map(f=>[f.id,f]));state.pageOrder=state.pageOrder.filter(p=>files.has(p.fileId)&&p.local<files.get(p.fileId).pages);state.pageOrder.forEach(p=>{if(!p.uid)p.uid=crypto.randomUUID()})}
function groupSourcePages(){ensurePageOrder();state.pageOrder=state.files.flatMap(f=>state.pageOrder.filter(p=>p.fileId===f.id))}
function pageSource(page=state.page){const item=(state.pageOrder||defaultPageOrder())[page-1];const file=state.files.find(f=>f.id===item?.fileId);return file?{file,local:item.local,uid:item.uid,start:page-item.local}:null}
function sourcePagePositions(id){const positions=(state.pageOrder||defaultPageOrder()).flatMap((p,n)=>p.fileId===id?[n+1]:[]);const ranges=[];for(let n=0;n<positions.length;n++){const start=positions[n];let end=start;while(positions[n+1]===end+1)end=positions[++n];ranges.push(start===end?String(start):`${start}–${end}`)}return ranges.join(', ')}
function capturePageState(){return {rotations:new Map((state.pageOrder||[]).map((p,n)=>[p.uid,state.rotation[n+1]||0])),current:pageIdentity(state.page-1)}}
function restorePageState(snapshot){ensurePageOrder();state.rotation={};state.pageOrder.forEach((p,n)=>{const angle=snapshot.rotations.get(p.uid);if(angle)state.rotation[n+1]=angle;if(snapshot.current===p.uid)state.page=n+1})}
function refreshEditingUI(){ensurePageOrder();state.page=Math.max(1,Math.min(state.page,total()));if(state.tab==='pages'&&$('.pages-stage')){const scroll=$('#paper-stage').scrollTop;syncPageCards();$('.files').innerHTML=state.files.map(fileMarkup).join('');bindSourceEvents();renderSourceThumbs();updateEditorLabels();updateOutputSummary();updateHistoryButtons();$('#paper-stage').scrollTop=scroll;decorate()}else render();scheduleDraft()}
function updateEditorLabels(){const source=pageSource();document.querySelectorAll('.file').forEach(el=>el.classList.toggle('selected',el.dataset.file===source?.file.id));$('.source-summary span')?.replaceChildren(document.createTextNode(`${total()} pages in your merged PDF`));if($('#page-jump')){$('#page-jump').max=total()||1;$('#page-jump').value=total()?state.page:0}const option=$('#page-range option[value=all]');if(option)option.textContent=`All pages (${total()})`;const current=$('#page-range option[value=current]');if(current)current.textContent=`Current page (${state.page})`;if($('.workflow-summary'))$('.workflow-summary').textContent=`${state.files.length} files · ${total()} pages`;document.querySelectorAll('[data-action=export]').forEach(b=>b.disabled=!total());if($('#status'))$('#status').textContent=`${state.files.length} files · ${total()} pages · Ready`;if($('.current-source'))$('.current-source').textContent=source?.file.name||'No document';document.querySelector('[data-action=prev]')?.toggleAttribute('disabled',state.page<=1);document.querySelector('[data-action=next]')?.toggleAttribute('disabled',state.page>=total())}
async function movePage(from,to){$('.workspace')?.classList.remove('drop-active');if(state.busy||from===to||from<0||to<0||to>=total())return;remember();const snap=capturePageState();const sourceUid=pageIdentity(from);let moving=state.selectedPages.has(sourceUid)?state.pageOrder.filter(p=>state.selectedPages.has(p.uid)):[state.pageOrder[from]];const movingIds=new Set(moving.map(p=>p.uid));const before=state.pageOrder.slice(0,to+(from<to?1:0)).filter(p=>!movingIds.has(p.uid)).length;state.pageOrder=state.pageOrder.filter(p=>!movingIds.has(p.uid));state.pageOrder.splice(before,0,...moving);snap.current=sourceUid;restorePageState(snap);state.workflow='review';state.completed=null;refreshEditingUI()}
function selectedIndices(){return state.pageOrder.flatMap((p,n)=>state.selectedPages.has(p.uid)?[n]:[])}
function setPageSelection(index,event={}){const item=state.pageOrder[index];if(!item)return;const anchor=state.pageOrder.findIndex(p=>p.uid===state.selectionAnchor);if(event.shiftKey&&anchor>=0){if(!event.ctrlKey&&!event.metaKey)state.selectedPages.clear();for(let n=Math.min(anchor,index);n<=Math.max(anchor,index);n++)state.selectedPages.add(state.pageOrder[n].uid)}else if(event.ctrlKey||event.metaKey||event.toggle){state.selectedPages.has(item.uid)?state.selectedPages.delete(item.uid):state.selectedPages.add(item.uid);state.selectionAnchor=item.uid}else{state.selectedPages=new Set([item.uid]);state.selectionAnchor=item.uid}state.page=index+1;syncPageCards();updateEditorLabels()}
async function editSelection(action){const indices=selectedIndices();if(!indices.length)return toast('Select one or more pages first.');if(action==='extract'){const bytes=await buildOutput(indices);downloadBytes(bytes,'Extracted pages.pdf');toast(`${indices.length} pages extracted. Your document is unchanged.`);return}remember();const snap=capturePageState();if(action==='delete'){state.pageOrder=state.pageOrder.filter(p=>!state.selectedPages.has(p.uid));state.selectedPages.clear();state.selectionAnchor=null}if(action==='duplicate'){const inserted=[];for(const [n,p]of state.pageOrder.entries()){inserted.push(p);if(state.selectedPages.has(p.uid)){const copy={...p,uid:crypto.randomUUID()};inserted.push(copy);snap.rotations.set(copy.uid,state.rotation[n+1]||0)}}state.pageOrder=inserted}if(action==='rotate'){for(const n of indices)snap.rotations.set(state.pageOrder[n].uid,((state.rotation[n+1]||0)+90)%360)}restorePageState(snap);state.completed=null;state.workflow='review';refreshEditingUI()}
function selectedPages(){const count=total();if(state.rangeMode==='current')return [state.page-1];if(state.rangeMode==='all')return Array.from({length:count},(_,n)=>n);const result=[];for(const part of state.customRange.split(',')){const m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw new RangeError('Enter pages such as 1-3, 5.');const start=Number(m[1]),end=Number(m[2]||m[1]);if(start<1||end>count||end<start)throw new RangeError(`Choose page numbers from 1 to ${count}.`);for(let n=start;n<=end;n++)if(!result.includes(n-1))result.push(n-1)}return result}
function updateOutputSummary(){let text,error='';try{const n=selectedPages().length;text=`${n} ${n===1?'page':'pages'} · ${state.rangeMode==='all'?'Complete document':'Selected pages'}`}catch(e){text='Check page range';error=state.customRange?e.message:''}if($('#export-summary'))$('#export-summary').textContent=text;if($('#range-error'))$('#range-error').textContent=error;if($('#custom-range'))$('#custom-range').setAttribute('aria-invalid',String(Boolean(error)))}
function toast(message){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4500)}
function decorate(){createIcons({icons,attrs:{'aria-hidden':'true'}})}
function total(){return state.pageOrder===null?state.files.reduce((n,f)=>n+f.pages,0):state.pageOrder.length}
function size(bytes){return bytes>1048576?`${(bytes/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(bytes/1024))} KB`}
function shell(){
$('#app').innerHTML=`<div class="app"><header class="titlebar" data-tauri-drag-region><div class="brand" aria-label="iFixPDF">${brandMark()}<span>iFixPDF</span></div><span>PDF workspace</span><div class="window-actions"><button aria-label="Minimize window" data-window="minimize">${icon('minus')}</button><button aria-label="Maximize window" data-window="toggleMaximize">${icon('square')}</button><button aria-label="Close window" data-window="close">${icon('x')}</button></div></header><aside class="sidebar"><button class="nav-item" data-view="home" title="Home">${icon('house')}<span class="nav-text">Home</span></button><button class="nav-item" data-view="combine" title="Merge PDFs">${icon('files')}<span class="nav-text">Merge PDFs</span></button><button class="nav-item" data-view="preview" title="Preview PDF">${icon('scan')}<span class="nav-text">Preview PDF</span></button><button class="nav-item" data-view="edit" title="Edit PDF">${icon('pencil')}<span class="nav-text">Edit PDF</span></button><div class="side-bottom"><button class="nav-item" data-view="settings" title="Settings">${icon('settings-2')}<span class="nav-text">Settings</span></button><div class="privacy">${icon('shield-check')}<span>Your documents.<br>On your device.</span></div></div></aside><main class="workspace"><header class="workspace-header"><div><h1 id="view-title">Merge PDFs</h1><div class="subtitle" id="view-subtitle">A few files. One well-ordered document.</div></div><div class="header-actions"><button class="secondary new-combine" data-action="new-combine">${icon('files')} New merge</button><button class="secondary" data-action="add">${icon('plus')} Add files</button><button class="secondary hidden" data-action="preview-print">${icon('printer')} Print PDF</button><button class="primary hidden" data-action="edit-current">${icon('pencil')} Edit PDF</button><button class="primary" data-action="export">${icon('download')} <span class="save-label">Save PDF</span></button></div></header><div id="content" style="display:contents"></div></main><footer class="statusbar"><span class="dot"></span><span id="status">Ready</span><span class="right" id="draft-status">Drafts saved on this device</span></footer></div><input id="file-input" class="hidden" type="file" accept="application/pdf,.pdf" multiple>`;
$('#file-input').onchange=e=>{const files=[...e.target.files];if(['preview','edit','home'].includes(state.view))openFileForView(files[0],state.view);else importFiles(files);e.target.value=''};
$('#app').addEventListener('click',handleClick);startUpdates(toast);
$('#app').addEventListener('change',handleChange);
$('#app').addEventListener('change',e=>{if(e.target.matches('[data-recent-check]')){const count=document.querySelectorAll('[data-recent-check]:checked').length;const b=document.querySelector('[data-action=merge-selected]');if(b)b.disabled=!count;if($('#recent-selection-count'))$('#recent-selection-count').textContent=count?'('+count+')':'';e.target.closest('.recent-file').classList.toggle('recent-selected',e.target.checked)}});
$('#app').addEventListener('input',e=>{if(e.target.id==='custom-range'){state.customRange=e.target.value;updateOutputSummary();scheduleDraft()}if(e.target.id==='output-name'){state.name=e.target.value;scheduleDraft()}});
let resizeTimer;new ResizeObserver(()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.fit&&state.tab==='document'&&!state.busy)renderPage()},100)}).observe($('.workspace'));
$('#app').addEventListener('dragover',e=>{e.preventDefault();$('.workspace').classList.add('drop-active')});
$('#app').addEventListener('dragleave',e=>{if(!e.relatedTarget||!$('#app').contains(e.relatedTarget))$('.workspace').classList.remove('drop-active')});
$('#app').addEventListener('drop',e=>{e.preventDefault();$('.workspace').classList.remove('drop-active');if(e.dataTransfer.files.length){if(['preview','edit','home'].includes(state.view))openFileForView(e.dataTransfer.files[0],state.view);else importFiles([...e.dataTransfer.files])}});
render();}
function historyRoute(params){window.history.replaceState(null,'',`index.html?${params}`)}
function render(){
const source=pageSource();if(source)state.selected=source.file.id;if(state.view==='home')historyRoute('view=home');
const titles={home:['Home','Recent PDFs and your current workspace.'],combine:['Merge PDFs','A few files. One well-ordered document.'],preview:['Preview PDF',state.files.length===1?state.name:'Read and inspect your document.'],edit:['Edit PDF',state.files.length===1?state.name:'Organize pages and save an edited copy.'],settings:['Settings','A workspace that works your way.']};
if(['preview','edit'].includes(state.view)&&state.files.length===1){const q=new URLSearchParams({recent:state.files[0].id});if(state.view==='edit')q.set('view','edit');historyRoute(q)}
$('#view-title').textContent=titles[state.view][0];$('#view-subtitle').textContent=titles[state.view][1];
document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
$('.workspace').classList.toggle('preview-only',state.view==='preview');$('.workspace').classList.toggle('edit-only',state.view==='edit');
const saveButton=document.querySelector('.header-actions [data-action=export]');saveButton.disabled=!total()||state.busy;saveButton.querySelector('.save-label').textContent=state.view==='combine'&&state.workflow==='review'?'Continue to save':'Save PDF';saveButton.setAttribute('aria-label',saveButton.querySelector('.save-label').textContent);document.querySelector('.new-combine').classList.toggle('hidden',state.view!=='combine'||!total()||state.workflow==='done');
document.querySelector('.header-actions [data-action=export]').classList.toggle('hidden',!['combine','edit'].includes(state.view)||(state.view==='combine'&&(!total()||state.workflow==='done')));document.querySelector('[data-action=edit-current]').classList.toggle('hidden',state.view!=='preview');document.querySelector('[data-action=edit-current]').disabled=!total();document.querySelector('[data-action=preview-print]').classList.toggle('hidden',state.view!=='preview'||!total());const openButton=document.querySelector('.header-actions [data-action=add]');openButton.classList.toggle('hidden',state.view==='settings');openButton.innerHTML=icon(['preview','edit','home'].includes(state.view)?'folder-open':'plus')+(['preview','edit','home'].includes(state.view)?' Open PDF':' Add files');$('#file-input').multiple=!['preview','edit','home'].includes(state.view);
if(state.view==='combine'&&state.workflow==='done')renderCombineDone();else if(state.view==='combine'&&!total()&&!state.busy)renderCombineStart();else if(state.view==='preview')renderPreview();else if(state.view==='edit'&&!total())renderEditEmpty();else if(state.view==='home')renderHome();else if(state.view==='settings')renderSettings();else renderEditor();
$('#status').textContent=state.busy?'Processing PDF…':state.files.length?`${state.files.length} files · ${total()} pages · Ready`:'Ready to add PDFs';
decorate();}
function fileMarkup(f,i){const start=1+state.files.slice(0,i).reduce((n,f)=>n+f.pages,0);return `<div class="file ${f.id===state.selected?'selected':''}" draggable="true" data-file="${f.id}"><button class="file-select" data-select-file="${f.id}" aria-label="Preview ${esc(f.name)}" aria-pressed="${f.id===state.selected}"><span class="grip">${icon('grip-vertical')}</span><span class="source-thumb"><img data-thumb="${f.id}" alt=""></span><span class="file-info"><span class="filename" title="${esc(f.name)}">${esc(f.name)}</span><span class="filemeta">${sourcePagePositions(f.id)?'Pages '+sourcePagePositions(f.id):'No pages included'} <span>·</span> ${size(f.bytes.length)}</span></span></button><div class="file-tools"><span>${(state.pageOrder||defaultPageOrder()).filter(p=>p.fileId===f.id).length} included</span><button data-move="${f.id}" data-dir="-1" title="Move up" aria-label="Move ${esc(f.name)} up" ${i===0?'disabled':''}>${icon('arrow-up')}</button><button data-move="${f.id}" data-dir="1" title="Move down" aria-label="Move ${esc(f.name)} down" ${i===state.files.length-1?'disabled':''}>${icon('arrow-down')}</button><button data-remove="${f.id}" title="Remove file" aria-label="Remove ${esc(f.name)}">${icon('x')}</button></div></div>`}
async function renderSourceThumbs(files=state.files){for(const f of files){let task=thumbnailCache.get(f.id);if(!task){task=(async()=>{const doc=await pdfjs.getDocument({data:f.bytes.slice()}).promise;const page=await doc.getPage(1);const vp=page.getViewport({scale:.18});const c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await page.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;const url=c.toDataURL();await doc.destroy();return url})();thumbnailCache.set(f.id,task)}try{const url=await task;const img=[...document.querySelectorAll('[data-thumb]')].find(el=>el.dataset.thumb===f.id);if(img)img.src=url}catch{thumbnailCache.delete(f.id)}}}
function workflowBar(){const stages=[['add','Add PDFs'],['review','Arrange & review'],['save','Save PDF'],['done','Done']];const current=state.workflow==='add'?0:state.workflow==='save'?2:state.workflow==='done'?3:1;return `<nav class="combine-workflow" aria-label="Merge PDF workflow"><ol>${stages.map(([id,label],n)=>`<li class="${n===current?'current':n<current?'complete':''}"><button ${n===current?'aria-current="step"':''} data-workflow="${id}" ${id==='done'||(!total()&&id!=='add')?'disabled':''}><span class="step-marker">${n<current?icon('circle-check'):n+1}</span><span>${label}</span></button></li>`).join('')}</ol><span class="workflow-summary">${total()?`${state.files.length} files · ${total()} pages`:'Start a new document'}</span></nav>`}
function newCombine(){if(state.busy)return;setView('combine');draftTimer=clearTimeout(draftTimer);state.savedDraft=null;draftChain=draftChain.catch(()=>{}).then(()=>writeDraft(null,'merge')).catch(()=>{});state.files=[];state.selectedPages.clear();state.pageOrder=null;state.rotation={};state.page=1;state.rangeMode='all';state.customRange='';state.name='Merged document.pdf';state.output='pdf';state.workflow='add';state.completed=null;state.showOutput=false;pdf=null;mergedBytes=null;render()}
function continueToSave(){if(!total())return toast('Add at least one PDF to continue.');state.workflow='save';state.output='pdf';state.tab='document';state.showOutput=matchMedia('(max-width:760px)').matches;render();requestAnimationFrame(()=>$('#output-name')?.focus())}
function renderCombineStart(){
$('#content').innerHTML=workflowBar()+`<section class="combine-start"><div class="combine-drop"><span class="combine-start-icon">${icon('files')}</span><h2>Choose PDFs to merge</h2><p>Add two or more PDFs, then put them in the order you need.</p><button class="primary" data-action="add">${icon('plus')} Add PDF files</button><span class="drop-caption">or drag and drop PDFs into this window</span>${state.savedDraft?.files.length?'<button class="secondary" data-action="restore-saved">Restore saved draft</button>':''}</div><div class="combine-instructions"><h3>From files to one PDF</h3><div>${icon('file-plus-2')}<p><strong>Add your PDFs</strong><span>Choose files from your device. Originals stay untouched.</span></p></div><div>${icon('grip-vertical')}<p><strong>Arrange and review</strong><span>Reorder files or individual pages. Preview and rotate pages as needed.</span></p></div><div>${icon('download')}<p><strong>Name and save</strong><span>Choose a file name and page range, then download one PDF.</span></p></div></div></section>`;decorate()}
function renderCombineDone(){const result=state.completed;$('#content').innerHTML=workflowBar()+`<section class="combine-done"><span class="done-icon">${icon('circle-check')}</span><h2>Your merged PDF is ready</h2><p>The download has been requested. Your source files are unchanged.</p><div class="completed-file">${icon('file-text')}<div><strong>${esc(result?.name||state.name)}</strong><span>${result?.pages||total()} pages · ${size(result?.bytes.length||0)} · PDF document</span></div></div><div class="done-actions"><button class="primary" data-action="open-result">${icon('folder-open')} Open merged PDF</button><button class="secondary" data-action="download-result">${icon('download')} Download again</button></div><div class="done-next"><button class="secondary" data-action="new-combine">Merge more PDFs</button><button data-action="back-to-review">Back to document</button><button data-view="home">View recent PDFs</button></div></section>`;decorate()}
function bindSourceEvents(){document.querySelectorAll('[data-file]').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('text/ifixpdf',el.dataset.file);el.ondragover=e=>e.preventDefault();el.ondrop=async e=>{const from=e.dataTransfer.getData('text/ifixpdf');if(!from)return;e.preventDefault();e.stopPropagation();const idx=state.files.findIndex(f=>f.id===from),to=state.files.findIndex(f=>f.id===el.dataset.file);remember();const snapshot=capturePageState();state.files.splice(to,0,state.files.splice(idx,1)[0]);groupSourcePages();restorePageState(snapshot);refreshEditingUI()}});
}
function previewToolbar(){return `<div class="toolbar"><button class="tab ${state.tab==='document'?'active':''}" data-tab="document">${icon('file-text')} Document</button><button class="tab ${state.tab==='pages'?'active':''}" data-tab="pages">${icon('layout-grid')} Pages</button><span class="toolbar-info">${icon('eye')} Read-only preview</span></div>`}
function renderPreview(){if(!total()){$('#content').innerHTML=`<section class="preview-empty empty">${icon('file-text')}<h2>Open a PDF to preview</h2><p>Read your document here. Use Edit PDF when you want to change its pages.</p><button class="primary" data-action="add">${icon('folder-open')} Open PDF</button></section>`;return}$('#content').innerHTML=previewToolbar()+`<section class="preview reader-preview" aria-label="PDF preview"><div class="preview-tools"><span>${esc(state.name)}</span><span class="spacer"></span><button data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><span class="zoom-value">${state.fit?'Fit':state.zoom+'%'}</span><button data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button data-action="fit" aria-label="Fit page" aria-pressed="${state.fit}">${icon('scan')}</button></div><div class="paper-stage" id="paper-stage"><div class="paper-wrap"><canvas class="paper" aria-label="PDF page preview"></canvas></div></div><div class="page-nav"><span class="reader-note">${total()} ${total()===1?'page':'pages'} · Read-only</span><div class="page-controls"><button data-action="prev" aria-label="Previous page" ${state.page<=1?'disabled':''}>${icon('chevron-left')}</button><label class="page-jump">Page <input id="page-jump" type="number" min="1" max="${total()}" value="${state.page}" aria-label="Go to page"> <span>of ${total()}</span></label><button data-action="next" aria-label="Next page" ${state.page>=total()?'disabled':''}>${icon('chevron-right')}</button></div></div></section>`;if(state.tab==='pages')renderReadOnlyPages();else renderPage()}
function renderReadOnlyPages(){const stage=$('#paper-stage');stage.classList.add('read-only-pages');stage.innerHTML='';state.pageOrder.forEach((item,n)=>{const button=document.createElement('button');button.className='read-page-thumbnail';button.setAttribute('aria-label',`Preview page ${n+1}`);button.innerHTML=`<img alt=""><span>Page ${n+1}</span>`;button.onclick=()=>{state.page=n+1;state.tab='document';render()};stage.append(button);thumbnailImage(item,n).then(url=>{button.querySelector('img').src=url}).catch(()=>{button.querySelector('img').alt='Preview unavailable'})})}
function renderEditEmpty(){$('#content').innerHTML=`<section class="preview-empty empty">${icon('pencil')}<h2>Open a PDF to edit</h2><p>Select, rearrange, rotate, duplicate, extract, or delete pages, then save a copy.</p><button class="primary" data-action="add">${icon('folder-open')} Open PDF</button></section>`}
async function openFileForView(file,view){if(!file)return;try{const bytes=new Uint8Array(await file.arrayBuffer());const doc=await PDFDocument.load(bytes);if(!doc.getPageCount())throw Error();const entry={id:crypto.randomUUID(),name:file.name,bytes,pages:doc.getPageCount()};await openRecentFile(entry,view==='edit'?'edit':'preview')}catch{toast('Could not open that PDF. Choose a valid, unlocked PDF.')}}
async function downloadPreviewCopy(){if(!total())return;try{downloadBytes(await buildOutput(Array.from({length:total()},(_,n)=>n)),state.name)}catch{toast('Could not save a copy of this PDF.')}}
async function printPreview(){if(!total())return;const bytes=await buildOutput(Array.from({length:total()},(_,n)=>n));const url=blobUrl(bytes);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Use Print in the PDF viewer to choose your printer.')}
function renderEditor(){
$('#content').innerHTML=(state.view==='combine'?workflowBar():'')+`<div class="toolbar"><button class="tab ${state.tab==='document'?'active':''}" data-tab="document">${icon('file-text')} Document</button><button class="tab ${state.tab==='pages'?'active':''}" data-tab="pages">${icon('layout-grid')} Pages</button><div class="history-controls"><button data-edit="undo" aria-label="Undo" title="Undo (Ctrl+Z)">${icon('undo-2')}</button><button data-edit="redo" aria-label="Redo" title="Redo (Ctrl+Shift+Z)">${icon('redo-2')}</button></div><span class="toolbar-info">${icon('lock-keyhole')} Files stay on this device</span><button class="mobile-panel-switch" data-action="output">${icon('sliders-horizontal')} Output</button></div><div class="editor ${state.showOutput?'show-output':''}"><section class="sources" aria-label="Source PDFs"><div class="panel-title">Source files <span class="count-badge">${state.files.length}</span></div><p class="hint">Drag files to arrange groups of pages.</p><div class="files">${state.files.map(fileMarkup).join('')}</div><button class="add-zone" data-action="add">${icon('file-plus-2')}<span>Add PDFs or drop them here</span></button><div class="source-summary">${icon('files')}<span>${total()} pages in your merged PDF</span></div></section><section class="preview" aria-label="PDF preview"><div class="preview-tools"><span id="preview-caption">${state.view==='edit'?'Document preview':'Merged preview'}</span><span class="spacer"></span><button data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><span class="zoom-value">${state.fit?'Fit':state.zoom+'%'}</span><button data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button data-action="fit" aria-label="Fit page" aria-pressed="${state.fit}" title="Fit whole page">${icon('scan')}</button><button data-action="rotate" aria-label="Rotate current page clockwise">${icon('rotate-cw')}</button></div><div class="paper-stage" id="paper-stage">${state.files.length?'<div class="paper-wrap"><canvas class="paper" aria-label="PDF page preview"></canvas></div>':`<div class="empty">${icon('file-plus-2')}<h2>Your next document starts here</h2><p>Add PDFs to preview and merge them.</p><button class="secondary" data-action="add">Add PDFs</button></div>`}</div><div class="page-nav"><span class="current-source" title="${esc(pageSource()?.file.name||'')}">${icon('file-text')} ${esc(pageSource()?.file.name||'No document')}</span><div class="page-controls"><button data-action="prev" aria-label="Previous page" ${state.page<=1?'disabled':''}>${icon('chevron-left')}</button><label class="page-jump">Page <input id="page-jump" type="number" min="1" max="${total()||1}" value="${total()?state.page:0}" aria-label="Go to page" ${!total()?'disabled':''}> <span>of ${total()}</span></label><button data-action="next" aria-label="Next page" ${state.page>=total()?'disabled':''}>${icon('chevron-right')}</button></div></div></section><aside class="output" aria-label="Output settings"><h2>${state.view==='combine'&&state.workflow==='save'?'Save merged PDF':state.view==='edit'?'Save edited PDF':'Output settings'}</h2>${state.view==='combine'&&state.workflow==='save'?'<p class="save-instruction">Check the name and pages, then save your document.</p>':''}<label class="field"><span>File name</span><input id="output-name" value="${esc(state.name)}" aria-label="Output file name"></label><div class="field"><span>Destination</span><div class="segmented"><button class="${state.output==='pdf'?'active':''}" data-dest="pdf">${icon('file-text')} PDF file</button><button class="${state.output==='print'?'active':''}" data-dest="print">${icon('printer')} Printer</button></div></div>${state.output==='pdf'?`<div class="quality-note">${icon('shield-check')}<div><strong>Original quality</strong><span>Source page content is preserved.</span></div></div>`:`<div class="settings-note">Print using your system dialog. Printer, copies, and paper settings are selected there.</div>`}<label class="field"><span>Pages</span><select id="page-range"><option value="all" ${state.rangeMode==='all'?'selected':''}>All pages (${total()})</option><option value="current" ${state.rangeMode==='current'?'selected':''}>Current page (${state.page})</option><option value="custom" ${state.rangeMode==='custom'?'selected':''}>Custom range…</option></select></label>${state.rangeMode==='custom'?`<label class="field range-field"><span>Page range</span><input id="custom-range" value="${esc(state.customRange)}" placeholder="e.g. 1-3, 5" aria-describedby="range-help range-error"><small id="range-help">Use commas and ranges, such as 1-3, 5.</small><small id="range-error" class="danger" role="alert"></small></label>`:''}<label class="check"><input id="bookmarks" type="checkbox" ${state.bookmarks?'checked':''}><span>Use file names as PDF title</span></label><label class="check"><input id="open-after" type="checkbox" ${state.openAfter?'checked':''}><span>Open PDF after saving</span></label><div class="output-foot"><div class="export-summary"><span>${icon('files')} ${state.output==='pdf'?(state.view==='edit'?'Edited document':'Merged document'):'Print document'}</span><strong id="export-summary"></strong></div><button class="primary wide" data-action="${state.output==='pdf'?'export':'queue'}" ${!total()||state.busy?'disabled':''}>${icon(state.output==='pdf'?'download':'printer')}${state.output==='pdf'?(state.view==='combine'&&state.workflow==='review'?'Continue to save':state.view==='edit'?'Save edited PDF':'Save merged PDF'):'Open for printing'}</button><p>${state.output==='pdf'?'Ready when you are. Originals stay untouched.':'Choose Print in the PDF viewer'}</p></div></aside></div>`;
bindSourceEvents();
updateOutputSummary();updateHistoryButtons();renderSourceThumbs();if(total()&&!state.busy) state.tab==='pages'?renderThumbnails():renderPage();}
async function renderPage(){const version=++renderVersion;const canvas=$('.paper'),stage=$('#paper-stage');if(!canvas||!stage||!total()||stage.clientHeight<1)return;try{const source=pageSource();if(!source)return;const document=await sourceView(source.file);const page=await document.getPage(source.local+1);if(version!==renderVersion||!canvas.isConnected)return;const rotation=(page.rotate+(state.rotation[state.page]||0))%360;const base=page.getViewport({scale:1,rotation});const style=getComputedStyle(stage);const width=stage.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight);const height=stage.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);const factor=state.fit?Math.min(width/base.width,height/base.height):state.zoom/100;state.actualZoom=Math.round(factor*100);const wrap=canvas.parentElement;wrap.style.width=`${Math.max(1,base.width*factor)}px`;wrap.style.maxWidth='none';const viewport=page.getViewport({scale:factor*Math.min(window.devicePixelRatio||1,2)*1.5,rotation});canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise}catch(e){if(e.name!=='RenderingCancelledException')toast('This page could not be previewed. Try another PDF.')}}
function pageTools(){return `${state.view==='edit'?'<button class="secondary split-command" data-action="split">'+icon('scissors')+' Split PDF</button>':''}<div class="page-selection-bar"><label><input id="select-all-pages" type="checkbox" aria-label="Select all pages"> <span id="selection-count">0 selected</span></label><button data-pages="rotate" aria-label="Rotate selected pages">${icon('rotate-cw')} Rotate</button><button data-pages="duplicate" aria-label="Duplicate selected pages">${icon('copy')} Duplicate</button><button data-pages="extract" aria-label="Extract selected pages">${icon('scissors')} Extract</button><button data-pages="delete" aria-label="Delete selected pages">${icon('trash-2')} Delete</button></div>`}
async function thumbnailImage(item,index){const file=state.files.find(f=>f.id===item.fileId),angle=state.rotation[index+1]||0,key=`${file.id}:${item.local}:${angle}`;if(!pageImages.has(key))pageImages.set(key,(async()=>{const doc=await sourceView(file);const page=await doc.getPage(item.local+1);const vp=page.getViewport({scale:.42,rotation:(page.rotate+angle)%360});const c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await page.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;return c.toDataURL()})());return pageImages.get(key)}
function createPageCard(uid){const card=document.createElement('div');card.className='page-card';card.draggable=true;card.dataset.uid=uid;card.innerHTML=`<label class="page-check"><input type="checkbox" aria-label="Select page"></label><button class="page-thumbnail"><img alt=""><span class="thumbnail-label"><strong></strong><span></span></span></button><div class="page-move-controls"><button>${icon('chevron-left')}</button><span></span><button>${icon('chevron-right')}</button></div>`;const index=()=>state.pageOrder.findIndex(p=>p.uid===card.dataset.uid),preview=card.querySelector('.page-thumbnail');preview.onclick=e=>setPageSelection(index(),e);preview.ondblclick=()=>{state.page=index()+1;state.tab='document';render()};preview.onkeydown=async e=>{if(e.altKey&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();e.stopPropagation();await movePage(index(),index()+(e.key==='ArrowLeft'?-1:1));preview.focus({preventScroll:true})}if(e.key==='Enter'){e.preventDefault();state.page=index()+1;state.tab='document';render()}};card.querySelector('.page-check input').onchange=e=>setPageSelection(index(),{toggle:true,shiftKey:e.shiftKey});const buttons=card.querySelectorAll('.page-move-controls button');buttons[0].onclick=()=>movePage(index(),index()-1);buttons[1].onclick=()=>movePage(index(),index()+1);card.ondragstart=e=>{if(!state.selectedPages.has(card.dataset.uid)){state.selectedPages=new Set([card.dataset.uid]);syncPageCards()}e.dataTransfer.setData('text/ifixpdf-page',String(index()));e.dataTransfer.effectAllowed='move';card.classList.add('dragging')};card.ondragend=()=>{$('.workspace')?.classList.remove('drop-active');document.querySelectorAll('.page-card').forEach(c=>c.classList.remove('dragging','drop-before','drop-after'))};card.ondragover=e=>{if(!e.dataTransfer.types.includes('text/ifixpdf-page'))return;e.preventDefault();e.stopPropagation();const after=e.clientX>card.getBoundingClientRect().left+card.clientWidth/2;card.classList.toggle('drop-after',after);card.classList.toggle('drop-before',!after)};card.ondragleave=e=>{if(!card.contains(e.relatedTarget))card.classList.remove('drop-before','drop-after')};card.ondrop=e=>{const raw=e.dataTransfer.getData('text/ifixpdf-page');if(raw==='')return;e.preventDefault();e.stopPropagation();const from=Number(raw),after=e.clientX>card.getBoundingClientRect().left+card.clientWidth/2;let to=index()+(after?1:0);if(from<to)to--;movePage(from,to)};return card}
function syncPageCards(){const stage=$('#paper-stage');if(!stage||!stage.classList.contains('pages-stage'))return;const existing=new Map([...stage.querySelectorAll('.page-card')].map(c=>[c.dataset.uid,c]));for(const [index,item]of state.pageOrder.entries()){let card=existing.get(item.uid);if(!card)card=createPageCard(item.uid);existing.delete(item.uid);const file=state.files.find(f=>f.id===item.fileId);card.dataset.pageIndex=index;card.setAttribute('aria-label',`Page ${index+1}, ${file.name}`);card.classList.toggle('is-selected',state.selectedPages.has(item.uid));card.classList.remove('drop-before','drop-after','dragging');const preview=card.querySelector('.page-thumbnail');preview.setAttribute('aria-label',`Preview page ${index+1}`);preview.setAttribute('aria-pressed',String(state.selectedPages.has(item.uid)));card.querySelector('.page-check input').checked=state.selectedPages.has(item.uid);card.querySelector('.page-check input').setAttribute('aria-label',`Select page ${index+1}`);card.querySelector('.thumbnail-label strong').textContent=index+1;const label=card.querySelector('.thumbnail-label>span');label.textContent=file.name;label.title=file.name;const controls=card.querySelectorAll('.page-move-controls button');controls[0].disabled=index===0;controls[0].setAttribute('aria-label',`Move page ${index+1} earlier`);controls[1].disabled=index===total()-1;controls[1].setAttribute('aria-label',`Move page ${index+1} later`);card.querySelector('.page-move-controls>span').textContent=`Page ${index+1}`;const img=card.querySelector('img');const key=`${item.fileId}:${item.local}:${state.rotation[index+1]||0}`;if(img.dataset.key!==key){img.dataset.key=key;thumbnailImage(item,index).then(url=>{if(img.dataset.key===key)img.src=url}).catch(()=>{img.alt='Preview unavailable'})}const expected=stage.querySelectorAll('.page-card')[index];if(expected!==card)stage.insertBefore(card,expected||null)}existing.forEach(c=>c.remove());const validIds=new Set(state.pageOrder.map(p=>p.uid));state.selectedPages=new Set([...state.selectedPages].filter(id=>validIds.has(id)));if(!validIds.has(state.selectionAnchor))state.selectionAnchor=[...state.selectedPages][0]||null;const count=selectedIndices().length;if($('#selection-count'))$('#selection-count').textContent=`${count} selected`;if($('#select-all-pages')){$('#select-all-pages').checked=count===total()&&total()>0;$('#select-all-pages').indeterminate=count>0&&count<total()}document.querySelectorAll('[data-pages]').forEach(b=>b.disabled=!count);decorate()}
async function renderThumbnails(){const stage=$('#paper-stage');if(!stage)return;stage.classList.add('pages-stage');stage.innerHTML=pageTools()+'<p class="page-drag-hint">Drag to reorder · Ctrl-click to select · Shift-click for a range · Double-click to preview</p>';syncPageCards()}
function selectFile(id){state.selected=id;ensurePageOrder();const index=state.pageOrder.findIndex(p=>p.fileId===id);if(index<0)return toast('No pages from this source are currently included. Use Undo to restore them.');state.page=1+index;state.tab='document';render()}
async function rebuild(){ensurePageOrder();state.page=Math.max(1,Math.min(state.page,total()));state.busy=false;mergedBytes=null;render();scheduleDraft()}
async function importFiles(files){if(state.busy)return;const added=[];for(const file of files){if(!file.name.toLowerCase().endsWith('.pdf')){toast(`${file.name} is not a PDF.`);continue}try{const bytes=new Uint8Array(await file.arrayBuffer());const doc=await PDFDocument.load(bytes);if(!doc.getPageCount())throw Error();const imported={id:crypto.randomUUID(),name:file.name,bytes,pages:doc.getPageCount()};await saveRecent(imported).catch(()=>{});added.push(imported)}catch{toast(`Could not open ${file.name}. Use a valid PDF without a password.`)}}if(added.length){setView('combine');remember();for(const imported of added){state.files.push(imported);if(state.pageOrder!==null)for(let local=0;local<imported.pages;local++)state.pageOrder.push({fileId:imported.id,local,uid:crypto.randomUUID()})}state.workflow='review';state.completed=null;state.selected=state.files.at(-1).id;await rebuild();toast(`${added.length} PDF${added.length===1?'':'s'} added`)}}
async function buildOutput(indices){const doc=await PDFDocument.create();for(const n of indices){const item=state.pageOrder[n],file=state.files.find(f=>f.id===item.fileId),src=await sourceDocument(file);const [page]=await doc.copyPages(src,[item.local]);page.setRotation(degrees((page.getRotation().angle+(state.rotation[n+1]||0))%360));doc.addPage(page)}doc.setTitle(state.bookmarks?state.files.map(f=>f.name.replace(/\.pdf$/i,'')).join(' · '):state.name);doc.setCreator('iFixPDF PDF workspace');return doc.save()}
async function outputBytes(){return buildOutput(selectedPages())}
function downloadBytes(bytes,name){const url=blobUrl(bytes);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function blobUrl(bytes){return URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}))}
async function exportPDF(){if(state.view==='combine'&&state.workflow==='review'){continueToSave();return}if(state.busy)return toast('Wait for PDF processing to finish.');if(!total())return toast('Add a PDF before saving.');await track(saveOutput)}
async function saveOutput(){try{const bytes=await outputBytes();await saveRecent({id:crypto.randomUUID(),name:state.name,bytes,pages:(await PDFDocument.load(bytes)).getPageCount()}).catch(()=>{});const url=blobUrl(bytes);const a=document.createElement('a');a.href=url;a.download=(state.name.trim().replace(/\.pdf$/i,'')||'Merged document')+'.pdf';a.click();if(state.openAfter)window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);state.completed={bytes,name:a.download,pages:(await PDFDocument.load(bytes)).getPageCount()};if(state.view==='edit'){toast('Your edited PDF is ready.');render()}else{state.workflow='done';setView('combine');render()}}catch(e){toast(e instanceof RangeError?e.message:'Could not save the PDF. Try a different file.')}}
async function renderHome(){
$('#content').innerHTML=`<section class="view editor-home"><div class="home-command-row"><button class="secondary" data-action="new-combine">${icon('files')} Merge PDFs</button><button class="secondary" data-action="merge-selected" disabled>${icon('files')} Merge selected <span id="recent-selection-count"></span></button><span>${icon('shield-check')} Stored on this device</span></div><div class="recent-heading"><h2>Recent PDFs</h2><span>Last opened</span></div><div class="recent-files"><p class="hint">Loading recent documents…</p></div></section>`;
decorate();try{const files=await listRecent();if(state.view!=='home')return;state.recents=files;$('.recent-files').innerHTML=files.length?files.map(f=>`<div class="recent-file" data-recent-row="${f.id}"><input class="recent-check" type="checkbox" data-recent-check="${f.id}" aria-label="Select ${esc(f.name)}"><span class="source-thumb"><img data-thumb="${f.id}" alt=""></span><button class="recent-name" data-recent="${f.id}"><strong>${esc(f.name)}</strong><span>${f.pages} pages · ${size(f.bytes.length)}</span></button><time>${new Date(f.modified).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</time><button class="secondary" data-recent="${f.id}" aria-label="Open ${esc(f.name)}">Open ${icon('chevron-right')}</button><button class="recent-more" data-recent-menu="${f.id}" aria-label="More actions for ${esc(f.name)}" aria-haspopup="menu">${icon('more-horizontal')}</button></div>`).join(''):`<div class="empty">${icon('folder-open')}<h2>No recent PDFs yet</h2><p>Add a PDF to start your workspace.</p><button class="secondary" data-action="add">Add PDFs</button></div>`;decorate();renderSourceThumbs(files);document.querySelectorAll('[data-recent-row]').forEach(row=>row.oncontextmenu=e=>{e.preventDefault();openRecentMenu(row.dataset.recentRow,e.clientX,e.clientY,row.querySelector('[data-recent-menu]'))})}catch{if(state.view==='home')$('.recent-files').innerHTML='<p class="hint">Recent documents could not be loaded. Add a PDF to continue.</p>'}}
function renderSettings(){$('#content').innerHTML=`<section class="view"><h2>Workspace preferences</h2><div class="settings-form"><div class="settings-row"><div>Document processing<p>PDF files are processed locally on this device.</p></div>${icon('shield-check')}</div><div class="settings-row"><div>Open PDF after saving<p>Preview the exported result in a separate tab.</p></div><input id="pref-open" aria-label="Open after saving" type="checkbox" ${state.openAfter?'checked':''}></div><div class="settings-row"><div>Interface<p>Light surfaces, compact controls, Windows typography.</p></div><span class="subtitle">Light</span></div><div class="settings-row"><div>Clear workspace<p>Remove documents from the current workspace.</p></div><button class="secondary danger" data-action="clear">Clear workspace</button></div><div class="settings-row" id="updates"></div></div></section>`;renderUpdates()}
async function flushDraft(){const other=state.workspace==='merge'?'document':'merge';await Promise.all([queueDraft(state.workspace),queueDraft(other,parked[other])])}
async function openRecentFile(file,target='preview'){setView(target);history.undo=[];history.redo=[];state.files=[file];state.pageOrder=null;state.selectedPages.clear();state.selectionAnchor=null;state.name=file.name;state.page=1;state.rotation={};state.rangeMode='all';state.customRange='';state.completed=null;state.workflow='review';state.tab=target==='edit'?'pages':'document';state.fit=true;state.showOutput=false;await saveRecent(file);await rebuild()}
async function handleClick(e){const b=e.target.closest('button');if(b){if(b.dataset.update){await updateAction(b.dataset.update,{persist:flushDraft,isWorking:()=>state.busy||working(),toast});return}if(b.dataset.recentMenu){const r=b.getBoundingClientRect();openRecentMenu(b.dataset.recentMenu,r.right,r.bottom,b);return}if(b.dataset.edit){undoRedo(b.dataset.edit);return}if(b.dataset.pages){await editSelection(b.dataset.pages);return}if(b.dataset.workflow){if(b.dataset.workflow==='add')$('#file-input').click();if(b.dataset.workflow==='review'&&total()){state.workflow='review';state.showOutput=false;render()}if(b.dataset.workflow==='save')continueToSave();return}if(b.dataset.recent){const f=state.recents?.find(f=>f.id===b.dataset.recent);if(f)await openRecentFile(f);return}if(b.dataset.selectFile){selectFile(b.dataset.selectFile);return}if(b.dataset.view){setView(b.dataset.view);if(state.view==='edit')state.tab='pages';if(state.view==='preview')state.tab='document';state.showOutput=false;render();return}if(b.dataset.window){if(window.__TAURI_INTERNALS__){const {getCurrentWindow}=await import('@tauri-apps/api/window');await getCurrentWindow()[b.dataset.window]()}else toast('Window controls are available in the Tauri desktop build.');return}if(b.dataset.tab){state.tab=b.dataset.tab;render();return}if(b.dataset.dest){state.output=b.dataset.dest;render();return}if(b.dataset.move){const i=state.files.findIndex(f=>f.id===b.dataset.move);const target=i+Number(b.dataset.dir);if(target>=0&&target<state.files.length){remember();const snapshot=capturePageState();[state.files[i],state.files[target]]=[state.files[target],state.files[i]];groupSourcePages();restorePageState(snapshot);await rebuild()}return}if(b.dataset.remove){remember();const snapshot=capturePageState();state.files=state.files.filter(f=>f.id!==b.dataset.remove);restorePageState(snapshot);state.selected=state.files[0]?.id;await rebuild();return}const a=b.dataset.action;if(a==='merge-selected'){await mergeRecents([...document.querySelectorAll('[data-recent-check]:checked')].map(c=>c.dataset.recentCheck));return}if(a==='split'){showSplitDialog({count:total(),name:state.name,build:buildOutput});return}if(a==='edit-current'){setView('edit');state.tab='pages';state.showOutput=false;render();return}if(a==='preview-print'){await printPreview();return}if(a==='restore-saved'&&state.savedDraft){restoreSnapshot(state.savedDraft);state.tab=state.view==='preview'?'document':'pages';render();return}if(a==='new-combine'){newCombine();return}if(a==='back-to-review'){state.workflow='review';render();return}if(a==='open-result'&&state.completed){const url=blobUrl(state.completed.bytes);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);return}if(a==='download-result'&&state.completed){const url=blobUrl(state.completed.bytes);const link=document.createElement('a');link.href=url;link.download=state.completed.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);return}if(a==='home')location.href='library.html';if(a==='add')$('#file-input').click();if(a==='export')await exportPDF();if(a==='queue')await printPreview();if(a==='project'){setView('combine');render()}if(a==='prev'&&state.page>1){state.page--;render()}if(a==='next'&&state.page<total()){state.page++;render()}if(a==='zoom-in'){state.zoom=Math.min(200,Math.round((state.fit?state.actualZoom:state.zoom)/10)*10+10);state.fit=false;render()}if(a==='zoom-out'){state.zoom=Math.max(25,Math.round((state.fit?state.actualZoom:state.zoom)/10)*10-10);state.fit=false;render()}if(a==='fit'){state.fit=true;render()}if(a==='rotate'&&total()){remember();state.rotation[state.page]=((state.rotation[state.page]||0)+90)%360;refreshEditingUI()}if(a==='output'){state.showOutput=!state.showOutput;render()}if(a==='clear'){draftTimer=clearTimeout(draftTimer);parked.document=blankWorkspace('document');parked.merge=blankWorkspace('merge');loadWorkspace(blankWorkspace(state.workspace));draftChain=draftChain.catch(()=>{}).then(()=>Promise.all([writeDraft(null,'document'),writeDraft(null,'merge')])).catch(()=>{});pdf=null;mergedBytes=null;render();toast('Workspace cleared.')}}else{const el=e.target.closest('[data-file]');if(el)selectFile(el.dataset.file)}}
function handleChange(e){if(e.target.id==='select-all-pages'){state.selectedPages=e.target.checked?new Set(state.pageOrder.map(p=>p.uid)):new Set();syncPageCards();return}if(e.target.id==='page-range'){state.rangeMode=e.target.value;render();if(state.rangeMode==='custom')$('#custom-range').focus()}if(e.target.id==='page-jump'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=1&&n<=total()){state.page=n;render()}else{e.target.value=state.page;toast(`Choose a page from 1 to ${total()}.`)}}if(e.target.id==='output-name'){state.name=e.target.value;scheduleDraft()};if(['open-after','pref-open'].includes(e.target.id))state.openAfter=e.target.checked;if(e.target.id==='bookmarks')state.bookmarks=e.target.checked}
shell();
function draftView(key,value){if(key==='merge')return 'combine';return value.view==='edit'?'edit':'preview'}
(async()=>{let drafts={};try{drafts=await readDrafts()}catch{}for(const [key,value] of Object.entries(drafts)){setView(draftView(key,value));state.savedDraft=value;if(value.files?.length){restoreSnapshot(value);state.tab=state.view==='preview'?'document':'pages'}}const params=new URLSearchParams(location.search);if(params.get('combine')==='new'){newCombine();return}const id=params.get('recent');if(id){const file=await getRecent(id);if(file){await openRecentFile(file,params.get('view')==='edit'?'edit':'preview');return}}const [newest]=Object.entries(drafts).filter(([,v])=>v.files?.length).sort((x,y)=>y[1].savedAt-x[1].savedAt);if(!params.has('view')&&newest){setView(draftView(...newest));render();toast('Your saved draft has been restored.');return}const view=params.get('view');setView(['preview','edit'].includes(view)?view:'home');state.tab=state.view==='edit'?'pages':'document';render()})();
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){if(['combine','edit'].includes(state.view)&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undoRedo(e.shiftKey?'redo':'undo');return}if(['combine','edit'].includes(state.view)&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();undoRedo('redo');return}if(['combine','edit'].includes(state.view)&&state.tab==='pages'&&$('.pages-stage')&&(e.key==='Delete'||e.key==='Backspace')){e.preventDefault();editSelection('delete');return}if(['combine','edit'].includes(state.view)&&state.tab==='pages'&&$('.pages-stage')&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();state.selectedPages=new Set(state.pageOrder.map(p=>p.uid));syncPageCards();return}}if((e.ctrlKey||e.metaKey)&&e.key==='o'){e.preventDefault();$('#file-input').click()}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();if(state.view==='preview')downloadPreviewCopy();else exportPDF()}if((e.ctrlKey||e.metaKey)&&e.key==='p'){e.preventDefault();if(state.view==='preview')printPreview();else if(['combine','edit'].includes(state.view))printPreview()}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(['combine','preview','edit'].includes(state.view)&&state.tab==='document'&&e.key==='ArrowRight'&&state.page<total()){state.page++;render()}if(['combine','preview','edit'].includes(state.view)&&state.tab==='document'&&e.key==='ArrowLeft'&&state.page>1){state.page--;render()}});

async function mergeRecents(ids){const files=ids.map(id=>state.recents?.find(f=>f.id===id)).filter(Boolean);if(!files.length)return;newCombine();state.files=[...files];state.pageOrder=null;state.name='Merged document.pdf';state.workflow='review';state.tab='pages';await rebuild();toast(files.length===1?'Add another PDF to merge with this document.':`${files.length} PDFs ready to merge.`)}
function openRecentMenu(id,x,y,trigger){document.querySelector('.recent-context-menu')?.remove();const file=state.recents?.find(f=>f.id===id);if(!file)return;const menu=document.createElement('div');menu.className='recent-context-menu';menu.role='menu';menu.setAttribute('aria-label',`Actions for ${file.name}`);menu.innerHTML=`<button role="menuitem" data-command="view">${icon('eye')} View PDF</button><button role="menuitem" data-command="edit">${icon('pencil')} Edit PDF</button><button role="menuitem" data-command="merge">${icon('files')} Merge PDFs</button><div class="menu-divider"></div><button role="menuitem" data-command="password">${icon('lock-keyhole')} Add password…</button>`;document.body.append(menu);decorate();menu.style.left=Math.max(8,Math.min(x,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-menu.offsetHeight-8))+'px';const close=(restore=false)=>{menu.remove();document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dismiss);if(restore)trigger?.focus()};const dismiss=()=>close();const outside=e=>{if(!menu.contains(e.target))close()};const keys=e=>{const items=[...menu.querySelectorAll('button')];let i=items.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close(true)}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();i=e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[i].focus()}if(e.key==='Tab')close()};menu.onclick=async e=>{const command=e.target.closest('[data-command]')?.dataset.command;if(!command)return;close(true);if(command==='view')await openRecentFile(file);if(command==='edit')await openRecentFile(file,'edit');if(command==='password')showPasswordDialog(file);if(command==='merge'){const selected=[...document.querySelectorAll('[data-recent-check]:checked')].map(c=>c.dataset.recentCheck);await mergeRecents([...new Set([id,...selected])])}};document.addEventListener('pointerdown',outside);document.addEventListener('keydown',keys);window.addEventListener('resize',dismiss);menu.querySelector('button').focus()}
